-- Canonical declarative source. Tenant and entity IDs are validated UUID strings by executable contracts.

CREATE TABLE organizations(org_id TEXT PRIMARY KEY,name TEXT NOT NULL,slow_moving_threshold_days INTEGER NOT NULL DEFAULT 90 CHECK(slow_moving_threshold_days>0));
CREATE TABLE organization_members(org_id TEXT NOT NULL REFERENCES organizations,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','analyst','viewer')),PRIMARY KEY(org_id,user_id));
CREATE TABLE imports(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL,payload JSONB NOT NULL,file_hash TEXT NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,file_hash));
CREATE TABLE snapshots(org_id TEXT NOT NULL,id TEXT NOT NULL,import_id TEXT NOT NULL,unit_external_id TEXT NOT NULL,snapshot_date DATE NOT NULL,project_external_id TEXT NOT NULL,zone_external_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,unit_external_id,snapshot_date),FOREIGN KEY(org_id,import_id) REFERENCES imports(org_id,id));
CREATE INDEX snapshots_latest ON snapshots(org_id,unit_external_id,snapshot_date DESC);
CREATE TABLE conversations(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL,created_by TEXT NOT NULL,PRIMARY KEY(org_id,id));
CREATE TABLE runs(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL,created_by TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,lease_until TIMESTAMPTZ,worker_id TEXT,slow_moving_threshold_days INTEGER NOT NULL DEFAULT 90 CHECK(slow_moving_threshold_days>0),fencing_token INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,created_by,idempotency_key));
CREATE INDEX runs_queue ON runs(status,lease_until,created_at);
CREATE TABLE run_snapshots(org_id TEXT NOT NULL,run_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,PRIMARY KEY(org_id,run_id,snapshot_id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id),FOREIGN KEY(org_id,snapshot_id) REFERENCES snapshots(org_id,id));
CREATE TABLE tasks(org_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,run_id,id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id));
CREATE TABLE artifacts(org_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,task_id TEXT NOT NULL,kind TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,run_id,id),UNIQUE(org_id,run_id,kind),FOREIGN KEY(org_id,run_id,task_id) REFERENCES tasks(org_id,run_id,id));
CREATE TABLE artifact_inputs(org_id TEXT NOT NULL,run_id TEXT NOT NULL,artifact_id TEXT NOT NULL,input_id TEXT NOT NULL,PRIMARY KEY(org_id,artifact_id,input_id),FOREIGN KEY(org_id,run_id,artifact_id) REFERENCES artifacts(org_id,run_id,id),FOREIGN KEY(org_id,run_id,input_id) REFERENCES artifacts(org_id,run_id,id));
CREATE TABLE artifact_snapshots(org_id TEXT NOT NULL,run_id TEXT NOT NULL,artifact_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,PRIMARY KEY(org_id,artifact_id,snapshot_id),FOREIGN KEY(org_id,run_id,artifact_id) REFERENCES artifacts(org_id,run_id,id),FOREIGN KEY(org_id,run_id,snapshot_id) REFERENCES run_snapshots(org_id,run_id,snapshot_id));
CREATE TABLE artifact_sources(org_id TEXT NOT NULL,artifact_id TEXT NOT NULL,import_id TEXT NOT NULL,PRIMARY KEY(org_id,artifact_id,import_id),FOREIGN KEY(org_id,artifact_id) REFERENCES artifacts(org_id,id),FOREIGN KEY(org_id,import_id) REFERENCES imports(org_id,id));
CREATE TABLE validations(org_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,run_id,id) REFERENCES artifacts(org_id,run_id,id));
CREATE TABLE events(org_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id));
CREATE TABLE messages(org_id TEXT NOT NULL,id TEXT NOT NULL,conversation_id TEXT NOT NULL,run_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,conversation_id) REFERENCES conversations(org_id,id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id));
CREATE TABLE definitions(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL,created_by TEXT NOT NULL,next_run_at TIMESTAMPTZ NOT NULL,enabled INTEGER NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id));
CREATE TABLE occurrences(org_id TEXT NOT NULL,id TEXT NOT NULL,definition_id TEXT NOT NULL,scheduled_for TIMESTAMPTZ NOT NULL,run_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,definition_id,scheduled_for),FOREIGN KEY(org_id,definition_id) REFERENCES definitions(org_id,id),FOREIGN KEY(org_id,run_id) REFERENCES runs(org_id,id));
CREATE TABLE reports(org_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,artifact_id TEXT NOT NULL,payload JSONB NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,run_id),FOREIGN KEY(org_id,run_id,artifact_id) REFERENCES artifacts(org_id,run_id,id));
CREATE TABLE report_exports(org_id TEXT NOT NULL,report_id TEXT NOT NULL,format TEXT NOT NULL CHECK(format IN ('json','csv')),storage_path TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,report_id,format),FOREIGN KEY(org_id,report_id) REFERENCES reports(org_id,id));

ALTER TABLE snapshots ADD COLUMN list_price numeric GENERATED ALWAYS AS ((payload->>'list_price')::numeric) STORED;
ALTER TABLE snapshots ADD COLUMN area_sqm numeric GENERATED ALWAYS AS ((payload->>'area_sqm')::numeric) STORED;
ALTER TABLE snapshots ADD CONSTRAINT snapshots_payload_scope CHECK(payload->>'org_id'=org_id AND payload->>'snapshot_id'=id AND payload->>'import_id'=import_id);
ALTER TABLE artifacts ADD CONSTRAINT artifacts_payload_scope CHECK(payload->>'org_id'=org_id AND payload->>'artifact_id'=id AND payload->>'run_id'=run_id AND payload->>'task_id'=task_id);
ALTER TABLE runs ADD CONSTRAINT runs_payload_scope CHECK(payload->>'org_id'=org_id AND payload->>'run_id'=id AND payload->>'created_by'=created_by);
ALTER TABLE artifacts ADD CONSTRAINT artifact_hash_shape CHECK(payload->>'content_hash' ~ '^[a-f0-9]{64}$');
CREATE INDEX snapshots_import ON snapshots(org_id,import_id);
CREATE INDEX run_snapshots_source ON run_snapshots(org_id,snapshot_id);
CREATE INDEX tasks_run ON tasks(org_id,run_id);
CREATE INDEX artifact_inputs_input ON artifact_inputs(org_id,run_id,input_id);
CREATE INDEX artifact_snapshots_source ON artifact_snapshots(org_id,run_id,snapshot_id);
CREATE INDEX artifact_sources_source ON artifact_sources(org_id,import_id);
CREATE INDEX validations_run ON validations(org_id,run_id);
CREATE INDEX events_run ON events(org_id,run_id);
CREATE INDEX messages_conversation ON messages(org_id,conversation_id);
CREATE INDEX messages_run ON messages(org_id,run_id);
CREATE INDEX definitions_due ON definitions(enabled,next_run_at);
CREATE INDEX occurrences_run ON occurrences(org_id,run_id);
CREATE INDEX reports_artifact ON reports(org_id,run_id,artifact_id);
CREATE INDEX members_user ON organization_members(user_id,org_id);
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC,anon,authenticated;
CREATE FUNCTION private.reject_immutable_change() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION 'immutable lineage record' USING ERRCODE='23514'; END;
$$;
REVOKE ALL ON FUNCTION private.reject_immutable_change() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER immutable_imports BEFORE UPDATE OR DELETE ON imports FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_snapshots BEFORE UPDATE OR DELETE ON snapshots FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_run_snapshots BEFORE UPDATE OR DELETE ON run_snapshots FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_artifacts BEFORE UPDATE OR DELETE ON artifacts FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_artifact_inputs BEFORE UPDATE OR DELETE ON artifact_inputs FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_artifact_snapshots BEFORE UPDATE OR DELETE ON artifact_snapshots FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_artifact_sources BEFORE UPDATE OR DELETE ON artifact_sources FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_occurrences BEFORE UPDATE OR DELETE ON occurrences FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
CREATE TRIGGER immutable_reports BEFORE UPDATE OR DELETE ON reports FOR EACH ROW EXECUTE FUNCTION private.reject_immutable_change();
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.organizations FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.organizations TO authenticated;
GRANT ALL ON public.organizations TO service_role;
CREATE POLICY workspace_read ON public.organizations FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=organizations.org_id AND m.user_id=(SELECT auth.uid())::text));
