CREATE POLICY source_import_read ON storage.objects FOR SELECT TO authenticated USING (
 bucket_id='source-imports'
 AND EXISTS(SELECT 1 FROM public.organization_members m WHERE m.org_id=(storage.foldername(name))[1] AND m.user_id=(SELECT auth.uid())::text)
 AND EXISTS(SELECT 1 FROM public.imports i WHERE i.org_id=(storage.foldername(name))[1] AND i.payload->>'storage_path'=name)
);

